-- Assessments. Apply after 010_content_management.sql. Safe to re-run; item data is upserted.
-- Generated by frontend/scripts/build-assessments.mts from scripts/assessment/*.json: edit those, then rebuild.
--
-- Answers are checked here, not in the browser:
-- - assessment_items holds each item's public prompt and, separately, the SHA-256 fingerprints
--   of the expected results plus the reference solution. No role can select it directly.
-- - The browser runs the learner's SQL/Python and saves only a fingerprint of what it produced.
-- - submit_assessment() compares fingerprints, scores the attempt, and only then returns the
--   reference solutions and explanations. The time limit is enforced with the server clock.

create table if not exists public.assessment_items (
  id text primary key check (id ~ '^as-(sql|py)-[0-9]{2,3}$'),
  kind text not null check (kind in ('sql', 'python')),
  title text not null,
  difficulty text not null check (difficulty in ('Easy', 'Medium', 'Hard')),
  topic text not null,
  prompt jsonb not null,
  answer jsonb not null,
  reference text not null,
  explanation text not null default '',
  active boolean not null default true
);
alter table public.assessment_items enable row level security;
-- Deliberately no policies: the items (answers included) are reachable only through the functions below.
revoke all on public.assessment_items from anon, authenticated;

create table if not exists public.assessment_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  config jsonb not null,
  items text[] not null,
  started_at timestamptz not null default now(),
  deadline timestamptz not null,
  submitted_at timestamptz,
  answers jsonb not null default '{}'::jsonb,
  results jsonb,
  score int,
  total int not null
);
create index if not exists assessment_attempts_user_idx on public.assessment_attempts (user_id, started_at desc);
alter table public.assessment_attempts enable row level security;
drop policy if exists assessment_attempts_read on public.assessment_attempts;
create policy assessment_attempts_read on public.assessment_attempts for select using (user_id = auth.uid() or public.is_admin());
-- No insert/update/delete policies: attempts change only through the functions below.

/** Public catalogue: prompts and counts, never answers. */
create or replace function public.assessment_catalog() returns table (id text, kind text, title text, difficulty text, topic text)
language sql stable security definer set search_path = public as $$
  select id, kind, title, difficulty, topic from assessment_items where active order by id;
$$;

/** Start an attempt: pick random active items for the config; returns the public prompts and the deadline. */
create or replace function public.start_assessment(p_kind text, p_difficulty text, p_topic text, p_count int, p_minutes int) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  picked text[];
  att assessment_attempts;
begin
  if auth.uid() is null then raise exception 'sign in to take an assessment'; end if;
  if p_kind not in ('sql', 'python', 'mixed') then raise exception 'invalid kind'; end if;
  if p_count not between 1 and 10 or p_minutes not between 5 and 120 then raise exception 'invalid size or time limit'; end if;
  if (select count(*) from assessment_attempts where user_id = auth.uid() and started_at > now() - interval '1 hour') >= 20 then
    raise exception 'too many assessments started in the last hour';
  end if;
  select array_agg(id) into picked from (
    select id from assessment_items
    where active and (p_kind = 'mixed' or kind = p_kind)
      and (p_difficulty is null or p_difficulty = '' or difficulty = p_difficulty)
      and (p_topic is null or p_topic = '' or topic = p_topic)
    order by random() limit p_count) s;
  if picked is null then raise exception 'no assessment items match these settings'; end if;
  insert into assessment_attempts (user_id, config, items, deadline, total)
    values (auth.uid(), jsonb_build_object('kind', p_kind, 'difficulty', p_difficulty, 'topic', p_topic, 'count', p_count, 'minutes', p_minutes),
            picked, now() + make_interval(mins => p_minutes), cardinality(picked))
    returning * into att;
  return jsonb_build_object('id', att.id, 'started_at', att.started_at, 'deadline', att.deadline,
    'items', (select jsonb_agg(jsonb_build_object('id', i.id, 'kind', i.kind, 'title', i.title, 'difficulty', i.difficulty, 'topic', i.topic) || i.prompt order by array_position(picked, i.id))
              from assessment_items i where i.id = any(picked)));
end $$;

/** Save the fingerprint(s) of the learner's latest answer to one item. No correctness feedback. */
create or replace function public.save_assessment_answer(p_attempt uuid, p_item text, p_answer jsonb) returns text
language plpgsql volatile security definer set search_path = public as $$
declare att assessment_attempts;
begin
  select * into att from assessment_attempts where id = p_attempt and user_id = auth.uid() for update;
  if not found then raise exception 'attempt not found'; end if;
  if att.submitted_at is not null then raise exception 'attempt already submitted'; end if;
  if now() > att.deadline + interval '30 seconds' then raise exception 'time is up'; end if;
  if not (p_item = any(att.items)) then raise exception 'item not in this attempt'; end if;
  if pg_column_size(p_answer) > 4000 then raise exception 'answer too large'; end if;
  update assessment_attempts set answers = answers || jsonb_build_object(p_item, p_answer || jsonb_build_object('at', now())) where id = p_attempt;
  return 'saved';
end $$;

/** Score an attempt (also after the deadline) and return the results with references. */
create or replace function public.submit_assessment(p_attempt uuid) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  att assessment_attempts;
  res jsonb := '[]'::jsonb;
  v_id text;
  v_item assessment_items;
  v_ans jsonb;
  v_ok boolean;
  v_passed int;
  v_cases int;
  v_score int := 0;
  v_out jsonb;
begin
  select * into att from assessment_attempts where id = p_attempt and user_id = auth.uid() for update;
  if not found then raise exception 'attempt not found'; end if;
  if att.submitted_at is not null then return att.results; end if;
  foreach v_id in array att.items loop
    select * into v_item from assessment_items where id = v_id;
    v_ans := att.answers -> v_id;
    if v_item.kind = 'sql' then
      v_ok := v_ans is not null and v_ans ->> 'sql' = v_item.answer ->> 'sql';
      v_passed := null; v_cases := null;
    else
      v_cases := jsonb_array_length(v_item.answer -> 'cases');
      select count(*) into v_passed from generate_series(0, v_cases - 1) i
        where v_ans is not null and v_ans -> 'cases' ->> i = v_item.answer -> 'cases' ->> i;
      v_ok := v_passed = v_cases;
    end if;
    if v_ok then v_score := v_score + 1; end if;
    res := res || jsonb_build_array(jsonb_build_object('id', v_id, 'passed', v_ok, 'answered', v_ans is not null,
      'cases_passed', v_passed, 'cases_total', v_cases, 'reference', v_item.reference, 'explanation', v_item.explanation));
  end loop;
  v_out := jsonb_build_object('id', att.id, 'score', v_score, 'total', att.total, 'started_at', att.started_at, 'submitted_at', now(), 'items', res);
  update assessment_attempts a set submitted_at = now(), score = v_score, results = v_out where a.id = p_attempt;
  return v_out;
end $$;

do $$
declare f text;
begin
  foreach f in array array['assessment_catalog()', 'start_assessment(text, text, text, int, int)', 'save_assessment_answer(uuid, text, jsonb)', 'submit_assessment(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
grant execute on function public.assessment_catalog() to anon;

-- Items (generated).
insert into public.assessment_items (id, kind, title, difficulty, topic, prompt, answer, reference, explanation) values
($df$as-sql-01$df$, 'sql', $df$Products per category$df$, $df$Easy$df$, $df$Aggregations$df$, $df${"problem":"The catalogue team wants to know how many products each category contains.","objective":"Return `category_name` and `product_count` (number of products in that category) for every category.","ordered":false}$df$::jsonb, $df${"sql":"c753b06ae551298681eb7987c1a749e6687c093fe8827736d5b83524b29de2ab"}$df$::jsonb, $df$SELECT c.category_name, COUNT(p.product_id) AS product_count FROM categories c LEFT JOIN products p ON p.category_id = c.category_id GROUP BY c.category_name$df$, $df$LEFT JOIN keeps categories without products; COUNT(p.product_id) counts only matched products, so an empty category shows 0.$df$),
($df$as-sql-02$df$, 'sql', $df$Discontinued stock still on hand$df$, $df$Easy$df$, $df$Filtering$df$, $df${"problem":"Warehouse wants a list of discontinued products that still have units in stock.","objective":"Return `product_name` and `units_in_stock` for discontinued products with at least one unit in stock.","ordered":false}$df$::jsonb, $df${"sql":"5f6753bec9d9164e76031a5172783e03072a77c775469e25725f36d87b53f552"}$df$::jsonb, $df$SELECT product_name, units_in_stock FROM products WHERE discontinued AND units_in_stock > 0$df$, $df$Two conditions in WHERE combined with AND: the product is discontinued and the stock is above zero.$df$),
($df$as-sql-03$df$, 'sql', $df$Orders per shipper$df$, $df$Easy$df$, $df$Aggregations$df$, $df${"problem":"Logistics compares carriers by how many orders each one shipped.","objective":"Return `company_name` of each shipper and `orders` (number of orders with that shipper as `ship_via`).","ordered":false}$df$::jsonb, $df${"sql":"bab4a6752024c451d1a25d255d803e7a8726aca226b0cced438376e6adb9c727"}$df$::jsonb, $df$SELECT s.company_name, COUNT(o.order_id) AS orders FROM shippers s LEFT JOIN orders o ON o.ship_via = s.shipper_id GROUP BY s.company_name$df$, $df$Orders reference shippers through ship_via; grouping by shipper and counting order ids gives the volume per carrier.$df$),
($df$as-sql-04$df$, 'sql', $df$Five most expensive products$df$, $df$Easy$df$, $df$Sorting$df$, $df${"problem":"Pricing wants the top end of the catalogue.","objective":"Return `product_name` and `unit_price` of the 5 most expensive products, most expensive first.","ordered":true}$df$::jsonb, $df${"sql":"7efa56c3cfe6fa2e8d100f48fa631760300a817b483b6d71cf22249ff9e4af83"}$df$::jsonb, $df$SELECT product_name, unit_price FROM products ORDER BY unit_price DESC LIMIT 5$df$, $df$ORDER BY unit_price DESC sorts from the highest price; LIMIT 5 keeps the first five rows. Row order is graded.$df$),
($df$as-sql-05$df$, 'sql', $df$Customers per country$df$, $df$Easy$df$, $df$Aggregations$df$, $df${"problem":"Sales leadership wants the size of each country's customer base.","objective":"Return `country` and `customers` (number of customers) for countries with at least 5 customers.","ordered":false}$df$::jsonb, $df${"sql":"4e4baaada430b2bafd4b8e69de12b83cb3b24bc5bbd7434429ce6f86e6b28a0b"}$df$::jsonb, $df$SELECT country, COUNT(*) AS customers FROM customers GROUP BY country HAVING COUNT(*) >= 5$df$, $df$GROUP BY country builds one row per country and HAVING filters the groups after counting.$df$),
($df$as-sql-06$df$, 'sql', $df$Orders handled by each employee$df$, $df$Easy$df$, $df$Joins$df$, $df${"problem":"HR reviews order handling per employee.","objective":"Return `first_name`, `last_name` and `orders` (number of orders they handled) for every employee.","ordered":false}$df$::jsonb, $df${"sql":"3365a0108ba25537c1356e18b9d615022615c473f081ed9b7f40a7d89894dfc4"}$df$::jsonb, $df$SELECT e.first_name, e.last_name, COUNT(o.order_id) AS orders FROM employees e LEFT JOIN orders o ON o.employee_id = e.employee_id GROUP BY e.employee_id, e.first_name, e.last_name$df$, $df$Group by the employee key (not just names, which may repeat) and count their orders.$df$),
($df$as-sql-07$df$, 'sql', $df$Orders shipped late$df$, $df$Easy$df$, $df$Filtering$df$, $df${"problem":"Customer service tracks orders that shipped after the required date.","objective":"Return `order_id`, `required_date` and `shipped_date` for orders shipped after their required date.","ordered":false}$df$::jsonb, $df${"sql":"126188857520844005ccc21e0b768c608b04da44ec94cbb20c6f3b5f6cb1ae3a"}$df$::jsonb, $df$SELECT order_id, required_date, shipped_date FROM orders WHERE shipped_date > required_date$df$, $df$Comparing two date columns row by row; orders not yet shipped have a NULL shipped_date and drop out because NULL > date is not true.$df$),
($df$as-sql-08$df$, 'sql', $df$Average freight by ship country$df$, $df$Easy$df$, $df$Aggregations$df$, $df${"problem":"Finance reviews freight cost by destination.","objective":"Return `ship_country` and `avg_freight` (average freight, rounded to 2 decimals) per ship country.","ordered":false}$df$::jsonb, $df${"sql":"c34e317cdebceefcb662d9114176eb1fd576a3158899b908aa8ffee218d3e56d"}$df$::jsonb, $df$SELECT ship_country, ROUND(AVG(freight), 2) AS avg_freight FROM orders GROUP BY ship_country$df$, $df$AVG per group, then ROUND to 2 decimals as asked.$df$),
($df$as-sql-09$df$, 'sql', $df$Revenue per category$df$, $df$Medium$df$, $df$Joins$df$, $df${"problem":"Finance wants net revenue by category (after discount).","objective":"Return `category_name` and `revenue` = sum of unit_price × quantity × (1 − discount) from order lines, rounded to 2 decimals.","ordered":false}$df$::jsonb, $df${"sql":"ef404518983ed6a4daae4248a2aa5e8969b6b5adda8b56993ca77f4523dbdd24"}$df$::jsonb, $df$SELECT c.category_name, ROUND(SUM(od.unit_price * od.quantity * (1 - od.discount))::numeric, 2) AS revenue FROM order_details od JOIN products p ON p.product_id = od.product_id JOIN categories c ON c.category_id = p.category_id GROUP BY c.category_name$df$, $df$Order lines join to products and then categories; revenue uses the line's own unit price, not the current catalogue price.$df$),
($df$as-sql-10$df$, 'sql', $df$Products priced above their category average$df$, $df$Medium$df$, $df$Subqueries$df$, $df${"problem":"Pricing flags products that cost more than the typical product in their category.","objective":"Return `product_name`, `category_id` and `unit_price` for products priced above the average unit price of their own category.","ordered":false}$df$::jsonb, $df${"sql":"6b75ff6355bec34db094daeb964fa0c5720524aec5e47f5a7ae6b9111fb35390"}$df$::jsonb, $df$SELECT p.product_name, p.category_id, p.unit_price FROM products p WHERE p.unit_price > (SELECT AVG(p2.unit_price) FROM products p2 WHERE p2.category_id = p.category_id)$df$, $df$A correlated subquery computes each product's category average; comparing against it keeps the above-average ones.$df$),
($df$as-sql-11$df$, 'sql', $df$Customers who never ordered$df$, $df$Medium$df$, $df$Joins$df$, $df${"problem":"Marketing wants customers with no orders at all.","objective":"Return `customer_id` and `company_name` of customers who have never placed an order.","ordered":false}$df$::jsonb, $df${"sql":"a67576cf7dd2a32847f430f4830d1996095eb6b06df5dd385243e2581bcd581e"}$df$::jsonb, $df$SELECT c.customer_id, c.company_name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id)$df$, $df$NOT EXISTS (or LEFT JOIN … IS NULL) keeps customers with no matching order; NOT IN would break if a customer_id were NULL.$df$),
($df$as-sql-12$df$, 'sql', $df$Orders per month in 1997$df$, $df$Medium$df$, $df$Date & Time$df$, $df${"problem":"Operations charts monthly order volume for 1997.","objective":"Return `month` (1–12) and `orders` for every month of 1997 that has orders, in month order.","ordered":true}$df$::jsonb, $df${"sql":"37139e7db792c85e0caf71d88ce2e8ef87df46f58f17ebeafb41dbe87af60096"}$df$::jsonb, $df$SELECT EXTRACT(MONTH FROM order_date)::int AS month, COUNT(*) AS orders FROM orders WHERE order_date >= DATE '1997-01-01' AND order_date < DATE '1998-01-01' GROUP BY 1 ORDER BY 1$df$, $df$A half-open date range selects 1997; EXTRACT(MONTH …) groups by month; ORDER BY month sorts it.$df$),
($df$as-sql-13$df$, 'sql', $df$Rank products within category by price$df$, $df$Medium$df$, $df$Window Functions$df$, $df${"problem":"Merchandising wants the price rank of every product inside its category.","objective":"Return `category_id`, `product_name`, `unit_price` and `price_rank` (1 = most expensive in the category; ties share a rank, with no gaps).","ordered":false}$df$::jsonb, $df${"sql":"7661735b8cb9b0ec9f913f18cf524e9d33288c00adba65c1beaf74e25424bcb3"}$df$::jsonb, $df$SELECT category_id, product_name, unit_price, DENSE_RANK() OVER (PARTITION BY category_id ORDER BY unit_price DESC) AS price_rank FROM products$df$, $df$PARTITION BY restarts the ranking per category; DENSE_RANK gives ties the same rank without gaps.$df$),
($df$as-sql-14$df$, 'sql', $df$Suppliers with many products$df$, $df$Medium$df$, $df$Aggregations$df$, $df${"problem":"Procurement reviews suppliers that provide a broad range.","objective":"Return `company_name` and `products` for suppliers that supply at least 3 products.","ordered":false}$df$::jsonb, $df${"sql":"1bd3183a6751226b4e103b703400f8181061eb8caf9140d83010a1f653c0ea34"}$df$::jsonb, $df$SELECT s.company_name, COUNT(*) AS products FROM suppliers s JOIN products p ON p.supplier_id = s.supplier_id GROUP BY s.supplier_id, s.company_name HAVING COUNT(*) >= 3$df$, $df$Join suppliers to their products, group per supplier and keep groups with 3 or more rows.$df$),
($df$as-sql-15$df$, 'sql', $df$Top customer per country by revenue$df$, $df$Medium$df$, $df$CTEs$df$, $df${"problem":"Account managers want the biggest customer in each country.","objective":"Return `country`, `company_name` and `revenue` (net, rounded to 2 decimals) of the customer with the highest revenue in each country.","ordered":false}$df$::jsonb, $df${"sql":"d6b97fd960c87c8a2401f6837d15f0b63a8f94b6060a78c7c8b288fb2b8e584c"}$df$::jsonb, $df$WITH rev AS (SELECT c.country, c.company_name, SUM(od.unit_price * od.quantity * (1 - od.discount)) AS r FROM customers c JOIN orders o ON o.customer_id = c.customer_id JOIN order_details od ON od.order_id = o.order_id GROUP BY c.customer_id, c.country, c.company_name), ranked AS (SELECT *, RANK() OVER (PARTITION BY country ORDER BY r DESC) AS rk FROM rev) SELECT country, company_name, ROUND(r::numeric, 2) AS revenue FROM ranked WHERE rk = 1$df$, $df$First compute revenue per customer, then rank within country and keep rank 1 (RANK keeps ties).$df$),
($df$as-sql-16$df$, 'sql', $df$Employees and their managers$df$, $df$Medium$df$, $df$Joins$df$, $df${"problem":"HR needs the reporting line.","objective":"Return `employee` (first and last name separated by a space) and `manager` (the same for the person they report to; NULL if none) for every employee.","ordered":false}$df$::jsonb, $df${"sql":"4e537f6795036f0d8e7ee4896b8b8d49264f6ed35672243fd35c1a1c774a33d7"}$df$::jsonb, $df$SELECT e.first_name || ' ' || e.last_name AS employee, m.first_name || ' ' || m.last_name AS manager FROM employees e LEFT JOIN employees m ON m.employee_id = e.reports_to$df$, $df$A self join on reports_to; LEFT JOIN keeps the top manager with a NULL manager.$df$),
($df$as-sql-17$df$, 'sql', $df$Running revenue by month$df$, $df$Hard$df$, $df$Window Functions$df$, $df${"problem":"Finance wants cumulative revenue through 1997.","objective":"For each month of 1997 return `month` (1–12), `revenue` (net, rounded to 2 decimals) and `running_revenue` (cumulative net revenue from January, rounded to 2 decimals), in month order.","ordered":true}$df$::jsonb, $df${"sql":"92a2410382b46ff82cf953b18f4cb74da16364f86afcc57ce78d61850dd5317c"}$df$::jsonb, $df$WITH m AS (SELECT EXTRACT(MONTH FROM o.order_date)::int AS month, SUM(od.unit_price * od.quantity * (1 - od.discount)) AS r FROM orders o JOIN order_details od ON od.order_id = o.order_id WHERE o.order_date >= DATE '1997-01-01' AND o.order_date < DATE '1998-01-01' GROUP BY 1) SELECT month, ROUND(r::numeric, 2) AS revenue, ROUND(SUM(r) OVER (ORDER BY month)::numeric, 2) AS running_revenue FROM m ORDER BY month$df$, $df$Aggregate per month first, then a window SUM ordered by month accumulates it; round only at the end so totals don't drift.$df$),
($df$as-sql-18$df$, 'sql', $df$Days between a customer's orders$df$, $df$Hard$df$, $df$Window Functions$df$, $df${"problem":"Retention analysts measure ordering gaps.","objective":"For customer `BONAP`, return each `order_id`, `order_date` and `days_since_previous` (days since that customer's previous order; NULL for the first), in date order.","ordered":true}$df$::jsonb, $df${"sql":"92a0ad476e1e51d1758e1c153ec10afdee2214b674b44142122e64fc4f1dfba8"}$df$::jsonb, $df$SELECT order_id, order_date, order_date - LAG(order_date) OVER (ORDER BY order_date, order_id) AS days_since_previous FROM orders WHERE customer_id = 'BONAP' ORDER BY order_date, order_id$df$, $df$LAG looks back one row in the window ordered by date; subtracting two dates gives whole days.$df$),
($df$as-sql-19$df$, 'sql', $df$Countries with customers but no suppliers$df$, $df$Hard$df$, $df$Set Operators$df$, $df${"problem":"Sourcing looks for markets without local suppliers.","objective":"Return `country` for each country that has customers but no suppliers.","ordered":false}$df$::jsonb, $df${"sql":"3eaaf73563021126de604ec70f2144538b7dd73c5cc46416447c9add2bf69488"}$df$::jsonb, $df$SELECT country FROM customers EXCEPT SELECT country FROM suppliers$df$, $df$EXCEPT returns distinct rows from the first query that are absent from the second.$df$),
($df$as-sql-20$df$, 'sql', $df$Products with a wide customer reach$df$, $df$Hard$df$, $df$CTEs$df$, $df${"problem":"Global merchandising looks for products with wide reach.","objective":"Return `product_name` and `countries` (number of distinct customer countries that ordered it) for products ordered from at least 5 different countries.","ordered":false}$df$::jsonb, $df${"sql":"02da38009529be9df4d786d26f35bbcc1b3ff24adc3f8fcdc952244e78d3df55"}$df$::jsonb, $df$SELECT p.product_name, COUNT(DISTINCT c.country) AS countries FROM order_details od JOIN orders o ON o.order_id = od.order_id JOIN customers c ON c.customer_id = o.customer_id JOIN products p ON p.product_id = od.product_id GROUP BY p.product_id, p.product_name HAVING COUNT(DISTINCT c.country) >= 5$df$, $df$COUNT(DISTINCT country) per product, filtered in HAVING; joins go order line → order → customer for the country.$df$),
($df$as-sql-21$df$, 'sql', $df$Orders above the customer's own average$df$, $df$Hard$df$, $df$Subqueries$df$, $df${"problem":"Account managers flag unusually large orders.","objective":"Return `order_id`, `customer_id` and `order_total` (net, rounded to 2 decimals) for orders whose total is above that customer's average order total.","ordered":false}$df$::jsonb, $df${"sql":"ac07bfa66ff5b5276b607bbfb71858ee493b600c39cd616a209adef0c38e474b"}$df$::jsonb, $df$WITH t AS (SELECT o.order_id, o.customer_id, SUM(od.unit_price * od.quantity * (1 - od.discount)) AS total FROM orders o JOIN order_details od ON od.order_id = o.order_id GROUP BY o.order_id, o.customer_id) SELECT order_id, customer_id, ROUND(total::numeric, 2) AS order_total FROM t WHERE total > (SELECT AVG(t2.total) FROM t t2 WHERE t2.customer_id = t.customer_id)$df$, $df$Totals per order first, then compare each with the average of the same customer's totals.$df$),
($df$as-sql-22$df$, 'sql', $df$Share of category revenue per product$df$, $df$Hard$df$, $df$Window Functions$df$, $df${"problem":"Category managers want each product's share of category revenue.","objective":"Return `category_id`, `product_name` and `share_pct` = product net revenue ÷ its category's net revenue × 100, rounded to 2 decimals.","ordered":false}$df$::jsonb, $df${"sql":"e90e04e8111de38a67a9027645ce5b52c5d273c80d217f653f36758b551d705b"}$df$::jsonb, $df$WITH r AS (SELECT p.category_id, p.product_name, SUM(od.unit_price * od.quantity * (1 - od.discount)) AS rev FROM order_details od JOIN products p ON p.product_id = od.product_id GROUP BY p.product_id, p.category_id, p.product_name) SELECT category_id, product_name, ROUND((100 * rev / SUM(rev) OVER (PARTITION BY category_id))::numeric, 2) AS share_pct FROM r$df$, $df$A window SUM partitioned by category gives each row its category total without collapsing rows.$df$),
($df$as-sql-23$df$, 'sql', $df$Repeat customers across years$df$, $df$Hard$df$, $df$CTEs$df$, $df${"problem":"Loyalty wants customers active in each year of the data.","objective":"Return `customer_id` for customers who placed orders in at least 2 different calendar years.","ordered":false}$df$::jsonb, $df${"sql":"b233a9c3aeb070d31f08f0818f387534b79f905e1dd4be2b85611d91d3b02d79"}$df$::jsonb, $df$SELECT customer_id FROM orders GROUP BY customer_id HAVING COUNT(DISTINCT EXTRACT(YEAR FROM order_date)) >= 2$df$, $df$Count the distinct order years per customer in HAVING; customers active in two or more years qualify.$df$),
($df$as-sql-24$df$, 'sql', $df$Second-best seller per category$df$, $df$Hard$df$, $df$Window Functions$df$, $df${"problem":"Merchandising wants the runner-up product in each category by units sold.","objective":"Return `category_id`, `product_name` and `units` (total quantity sold) for the product ranked second by units within each category (ties share a rank).","ordered":false}$df$::jsonb, $df${"sql":"d842860caadb93d440c73e66940adf6c607c4b653dfea42250cf6fad29ad1298"}$df$::jsonb, $df$WITH u AS (SELECT p.category_id, p.product_name, SUM(od.quantity) AS units FROM order_details od JOIN products p ON p.product_id = od.product_id GROUP BY p.product_id, p.category_id, p.product_name), r AS (SELECT *, DENSE_RANK() OVER (PARTITION BY category_id ORDER BY units DESC) AS rk FROM u) SELECT category_id, product_name, units FROM r WHERE rk = 2$df$, $df$Rank by units per category with DENSE_RANK and keep rank 2; ties both appear.$df$),
($df$as-py-01$df$, 'python', $df$Normalise email addresses$df$, $df$Easy$df$, $df$Data cleaning$df$, $df${"problem":"Sign-up data arrives with inconsistent emails. Write `normalise_emails(emails)` returning the unique, trimmed, lower-cased emails that contain exactly one `@`, in first-seen order.","starter":"def normalise_emails(emails):\n    raise NotImplementedError\n","example":"normalise_emails([' Ana@X.com', 'ana@x.com', 'bad', 'b@y.org'])  ->  ['ana@x.com', 'b@y.org']","cases":["normalise_emails([])","normalise_emails([' Ana@X.com', 'ana@x.com', 'bad', 'b@y.org'])","normalise_emails([None, 'a@@b.com', 'C@D.COM ', 'c@d.com'])","normalise_emails(['x@y.z'] * 3 + ['  '])"]}$df$::jsonb, $df${"cases":["ea901b692e0075fd3aa505be2746eb24aa6a7ccfec5956f5ba081eedb4d4fb15","803ecb618e39a564acf252e7daa0a26201ef2a915e03d268685b9dcd09db7415","f17effa0f558743f08ad4de05cf83e87bc476ee462d3ff7edd272544e710b504","f972d846cc2c37b1fe4c26b09f0c192f19a199e45b2315a41e3e5ad181d56ba9"]}$df$::jsonb, $df$def normalise_emails(emails):
    seen, out = set(), []
    for e in emails:
        if not isinstance(e, str):
            continue
        e = e.strip().lower()
        if e.count('@') != 1 or e in seen:
            continue
        seen.add(e)
        out.append(e)
    return out
$df$, $df$Strip and lower-case before the duplicate check so variants collapse; a set gives O(1) membership while the list keeps the order.$df$),
($df$as-py-02$df$, 'python', $df$Revenue per region$df$, $df$Easy$df$, $df$Aggregation$df$, $df${"problem":"Write `revenue_by_region(rows)` for rows like `{'region': 'EU', 'amount': 12.5}`. Return a dict region → total amount rounded to 2 decimals. Rows without a region or with a non-numeric amount are skipped.","starter":"def revenue_by_region(rows):\n    raise NotImplementedError\n","example":"revenue_by_region([{'region': 'EU', 'amount': 10}, {'region': 'EU', 'amount': 2.5}])  ->  {'EU': 12.5}","cases":["revenue_by_region([])","revenue_by_region([{'region': 'EU', 'amount': 10}, {'region': 'EU', 'amount': 2.5}, {'region': 'US', 'amount': 1}])","revenue_by_region([{'amount': 5}, {'region': 'EU', 'amount': '7'}, {'region': 'EU', 'amount': None}, {'region': 'EU', 'amount': True}])","revenue_by_region([{'region': 'APAC', 'amount': 0.1}] * 3)"]}$df$::jsonb, $df${"cases":["396565b27f4d1f8b9c430e31152f42bedc65aaf150b9b69949f13be5a22e5e94","32c88bd5ce39dbfba5232e26d83b9bb4b4e8cee037506bb54fdbc03419ab9b1c","396565b27f4d1f8b9c430e31152f42bedc65aaf150b9b69949f13be5a22e5e94","61ffafdd78c0ba4a858011a4fceb644fcbc519bf4ae78501444340ec2001b7cf"]}$df$::jsonb, $df$def revenue_by_region(rows):
    out = {}
    for r in rows:
        region, amt = r.get('region'), r.get('amount')
        if not region or isinstance(amt, bool) or not isinstance(amt, (int, float)):
            continue
        out[region] = round(out.get(region, 0) + amt, 2)
    return out
$df$, $df$dict.get avoids KeyError on missing fields; checking the type (and excluding bool, which is an int) skips bad amounts; rounding keeps totals at 2 decimals.$df$),
($df$as-py-03$df$, 'python', $df$Count HTTP status classes$df$, $df$Easy$df$, $df$Parsing$df$, $df${"problem":"Write `status_classes(lines)` for access-log lines like `GET /x 404 12ms`. Return a dict with keys '2xx', '3xx', '4xx', '5xx' counting the status code (the third field). Lines that don't have a 3-digit status there are ignored; classes with no lines are omitted.","starter":"def status_classes(lines):\n    raise NotImplementedError\n","example":"status_classes(['GET / 200 3ms', 'GET /x 404 1ms'])  ->  {'2xx': 1, '4xx': 1}","cases":["status_classes([])","status_classes(['GET / 200 3ms', 'GET /x 404 1ms', 'POST /y 201 9ms'])","status_classes(['bad line', 'GET / 99 1ms', 'GET / 600 1ms', 'GET / 503 2ms'])","status_classes(['PUT /a 302 1ms'] * 4)"]}$df$::jsonb, $df${"cases":["396565b27f4d1f8b9c430e31152f42bedc65aaf150b9b69949f13be5a22e5e94","cd4846e25d2b23f7f01943035859fa7a2e8cc545ee06360105d3bd89e62ba10f","3d531f1c730a5eddca7ee2c8d3b6f4ff7e6e600e4dc0f94bf6c4087cacf0c2b2","e0be90557d854edc42603582c4036a5f64186e4e8c14d01e035768f312fc4fc7"]}$df$::jsonb, $df$def status_classes(lines):
    out = {}
    for line in lines:
        parts = line.split()
        if len(parts) < 3 or not (parts[2].isdigit() and len(parts[2]) == 3) or parts[2][0] not in '2345':
            continue
        k = parts[2][0] + 'xx'
        out[k] = out.get(k, 0) + 1
    return out
$df$, $df$Split on whitespace, validate the field before using it, and bucket by the first digit.$df$),
($df$as-py-04$df$, 'python', $df$Latest record per id$df$, $df$Easy$df$, $df$Deduplication$df$, $df${"problem":"Write `latest_per_id(rows)` for rows with 'id' and 'updated_at' (ISO strings). Return one row per id, the one with the greatest updated_at, as a list sorted by id.","starter":"def latest_per_id(rows):\n    raise NotImplementedError\n","example":"latest_per_id([{'id': 1, 'updated_at': '2024-01-01'}, {'id': 1, 'updated_at': '2024-02-01'}])  ->  [{'id': 1, 'updated_at': '2024-02-01'}]","cases":["latest_per_id([])","latest_per_id([{'id': 2, 'updated_at': '2024-01-01', 'v': 'a'}, {'id': 1, 'updated_at': '2024-03-01', 'v': 'b'}, {'id': 2, 'updated_at': '2024-05-01', 'v': 'c'}])","latest_per_id([{'id': 1, 'updated_at': '2024-01-01', 'v': 'first'}, {'id': 1, 'updated_at': '2024-01-01', 'v': 'tie'}])"]}$df$::jsonb, $df${"cases":["ea901b692e0075fd3aa505be2746eb24aa6a7ccfec5956f5ba081eedb4d4fb15","de308cfdef8f5e740bb2d48b308c82c47f730840c0a03657b4719b56ee058ae0","bb7827e2acb4f2bd8b823c84c36e844bcda96b66e2a85834d7a694bd93826d2c"]}$df$::jsonb, $df$def latest_per_id(rows):
    best = {}
    for r in rows:
        cur = best.get(r['id'])
        if cur is None or r['updated_at'] > cur['updated_at']:
            best[r['id']] = r
    return [best[k] for k in sorted(best)]
$df$, $df$Keep the best row per id in a dict; ISO timestamps compare correctly as strings; a tie keeps the first row because only a strictly greater value replaces it.$df$),
($df$as-py-05$df$, 'python', $df$Flatten an API record$df$, $df$Medium$df$, $df$JSON$df$, $df${"problem":"Write `flatten(record, sep='.')` that flattens nested dicts into one level with joined keys. Lists are kept as values; empty nested dicts disappear.","starter":"def flatten(record, sep='.'):\n    raise NotImplementedError\n","example":"flatten({'a': {'b': 1}, 'c': 2})  ->  {'a.b': 1, 'c': 2}","cases":["flatten({})","flatten({'a': {'b': {'c': 1}}, 'd': [1, {'e': 2}]})","flatten({'a': {}, 'b': None}, sep='__')","flatten({'user': {'id': 7, 'tags': ['x']}, 'ok': True})"]}$df$::jsonb, $df${"cases":["396565b27f4d1f8b9c430e31152f42bedc65aaf150b9b69949f13be5a22e5e94","5e7be21795921da592dc1c1adbfe9e537047d51383f1616720ff17a4c6d0aca6","4ef45d02ff1848e5e0f0647903cf6922cf531fa523776aae33d56344ea418deb","9c8f6b07780e41dc69f63e81eb9bb7bde59cc808396d3e428d93b01942d25b3e"]}$df$::jsonb, $df$def flatten(record, sep='.'):
    out = {}
    def walk(d, prefix):
        for k, v in d.items():
            key = f'{prefix}{sep}{k}' if prefix else str(k)
            if isinstance(v, dict):
                walk(v, key)
            else:
                out[key] = v
    walk(record, '')
    return out
$df$, $df$Recursive walk carrying the key prefix; only dict values recurse, so lists stay as values and empty dicts add nothing.$df$),
($df$as-py-06$df$, 'python', $df$Validate rows against a schema$df$, $df$Medium$df$, $df$Validation$df$, $df${"problem":"Write `validate(rows, schema)` where schema maps field → type (int, float, str). Return a tuple (valid_rows, errors): a row is valid when every schema field is present with the right type (bool doesn't count as int/float; int is accepted for float). errors is a list of (row_index, sorted list of bad fields).","starter":"def validate(rows, schema):\n    raise NotImplementedError\n","example":"validate([{'id': 1}, {'id': 'x'}], {'id': int})  ->  ([{'id': 1}], [(1, ['id'])])","cases":["validate([], {'id': int})","validate([{'id': 1, 'p': 2}, {'id': 'x', 'p': 1.5}, {'p': True}], {'id': int, 'p': float})","validate([{'name': 'a'}, {'name': None}], {'name': str})"]}$df$::jsonb, $df${"cases":["6da72e6ba84284c5980e05ba7832182dfd2985dd56a9573291778f262e6a820c","ea4f84ba49a4b3271762391a1a03c4a6c7d53ec88c9f8357a99e5ecbc39355aa","8705602632f17ed5da8fa1bc7cfa461618d5543440ee784294dd0f033718e9e1"]}$df$::jsonb, $df$def validate(rows, schema):
    good, errors = [], []
    for i, r in enumerate(rows):
        bad = []
        for f, t in schema.items():
            v = r.get(f)
            ok = v is not None and not isinstance(v, bool) and (isinstance(v, t) or (t is float and isinstance(v, int)))
            if not ok:
                bad.append(f)
        if bad:
            errors.append((i, sorted(bad)))
        else:
            good.append(r)
    return good, errors
$df$, $df$Check each field independently and collect every failure; bool is excluded explicitly because it is a subclass of int.$df$),
($df$as-py-07$df$, 'python', $df$Batches by size and weight$df$, $df$Medium$df$, $df$Batching$df$, $df${"problem":"Write `batches(items, max_items, max_weight)` for items `(id, weight)`. Group them in order into batches that hold at most max_items items and at most max_weight total weight; an item heavier than max_weight goes alone in its own batch. Return a list of lists of ids.","starter":"def batches(items, max_items, max_weight):\n    raise NotImplementedError\n","example":"batches([('a', 3), ('b', 3), ('c', 3)], 5, 6)  ->  [['a', 'b'], ['c']]","cases":["batches([], 3, 10)","batches([('a', 3), ('b', 3), ('c', 3)], 5, 6)","batches([('a', 1), ('b', 20), ('c', 1), ('d', 1)], 2, 5)","batches([(str(n), 1) for n in range(7)], 3, 100)"]}$df$::jsonb, $df${"cases":["ea901b692e0075fd3aa505be2746eb24aa6a7ccfec5956f5ba081eedb4d4fb15","f6902b8f19934b20bf348c68cb1c7f8d4fb2a48e7265a7d6d6bba6045904b004","bfc092249de681a9f428491501f0c1e557f61b18e5b5519f281b732b54c23deb","2326eb5fb970501bf47afc79695261b8ff026b3071ae9c448e42a4ac026d1bd1"]}$df$::jsonb, $df$def batches(items, max_items, max_weight):
    out, cur, w = [], [], 0
    for i, wt in items:
        if cur and (len(cur) >= max_items or w + wt > max_weight):
            out.append(cur)
            cur, w = [], 0
        cur.append(i)
        w += wt
        if w > max_weight:
            out.append(cur)
            cur, w = [], 0
    if cur:
        out.append(cur)
    return out
$df$, $df$Close the current batch before adding an item that would break a limit; an oversized item is flushed immediately so it travels alone.$df$),
($df$as-py-08$df$, 'python', $df$Rows after the watermark$df$, $df$Medium$df$, $df$Incremental loads$df$, $df${"problem":"Write `incremental(rows, watermark)` for rows with an ISO 'ts'. Return (new_rows sorted by ts then id, new_watermark): rows strictly newer than the watermark (None means everything), and the max ts loaded, or the old watermark if nothing loaded.","starter":"def incremental(rows, watermark):\n    raise NotImplementedError\n","example":"incremental([{'id': 1, 'ts': '2024-01-02'}], '2024-01-01')  ->  ([{'id': 1, 'ts': '2024-01-02'}], '2024-01-02')","cases":["incremental([], None)","incremental([{'id': 2, 'ts': '2024-01-03'}, {'id': 1, 'ts': '2024-01-03'}, {'id': 3, 'ts': '2024-01-01'}], '2024-01-01')","incremental([{'id': 1, 'ts': None}, {'id': 2, 'ts': '2024-01-01'}], '2024-02-01')","incremental([{'id': 1, 'ts': '2024-01-01'}], None)"]}$df$::jsonb, $df${"cases":["5fbc996c5cbd50d7f9fb6313c2474eeb005aed21b8e5d9934ee07c7c6efaeedd","ad58a7c8d3a800e7cf3c85dae736145a05b36f62ef8e9a42ec6fb18104a77816","92f522506ccc18f2f6d6d0d2f2b9a0f66b4ced9ebdd9c6f179d5ccff7c5e9bd1","e5068142f64e8d351470c7a5ba6c3c9f4827e58440e395a2d6facd2ea749c342"]}$df$::jsonb, $df$def incremental(rows, watermark):
    new = sorted((r for r in rows if r.get('ts') and (watermark is None or r['ts'] > watermark)), key=lambda r: (r['ts'], r['id']))
    return new, (new[-1]['ts'] if new else watermark)
$df$, $df$Strictly-greater filtering avoids reloading the boundary row; sorting gives a deterministic load order and the last row's ts becomes the watermark.$df$),
($df$as-py-09$df$, 'python', $df$Reconcile two extracts$df$, $df$Hard$df$, $df$Reconciliation$df$, $df${"problem":"Write `reconcile(source, target, key, fields)` comparing two lists of dicts by `key`. Return a dict with 'missing' (keys only in source), 'extra' (only in target) and 'changed' (keys in both where any of `fields` differs), each a sorted list.","starter":"def reconcile(source, target, key, fields):\n    raise NotImplementedError\n","example":"reconcile([{'id': 1, 'a': 1}], [{'id': 1, 'a': 2}], 'id', ['a'])  ->  {'missing': [], 'extra': [], 'changed': [1]}","cases":["reconcile([], [], 'id', ['a'])","reconcile([{'id': 1, 'a': 1}, {'id': 2, 'a': 2}], [{'id': 2, 'a': 3}, {'id': 3, 'a': 1}], 'id', ['a'])","reconcile([{'id': 'x', 'a': 1, 'b': 1}], [{'id': 'x', 'a': 1, 'b': 9}], 'id', ['a'])","reconcile([{'id': 1, 'a': None}], [{'id': 1}], 'id', ['a'])"]}$df$::jsonb, $df${"cases":["c1eb0995f864bfb5efa13fdf50feff586ddbcc75f368c23d67900ca1640b1a16","0687e5f13db9edf406dfb8058753f9a5c2e85216ae015d99fab77295c8b0ec65","c1eb0995f864bfb5efa13fdf50feff586ddbcc75f368c23d67900ca1640b1a16","c1eb0995f864bfb5efa13fdf50feff586ddbcc75f368c23d67900ca1640b1a16"]}$df$::jsonb, $df$def reconcile(source, target, key, fields):
    s = {r[key]: r for r in source}
    t = {r[key]: r for r in target}
    return {
        'missing': sorted(s.keys() - t.keys()),
        'extra': sorted(t.keys() - s.keys()),
        'changed': sorted(k for k in s.keys() & t.keys() if any(s[k].get(f) != t[k].get(f) for f in fields)),
    }
$df$, $df$Index both sides by key, then set differences give missing/extra and the intersection is compared field by field (missing fields compare as None).$df$),
($df$as-py-10$df$, 'python', $df$Task run order with levels$df$, $df$Hard$df$, $df$Orchestration$df$, $df${"problem":"Write `levels(deps)` where deps maps task → list of upstream tasks. Return a list of levels (each a sorted list) where every task appears after all its upstream tasks, as early as possible. Tasks that only appear as upstreams count too. Raise ValueError on a cycle.","starter":"def levels(deps):\n    raise NotImplementedError\n","example":"levels({'b': ['a'], 'c': ['a', 'b']})  ->  [['a'], ['b'], ['c']]","cases":["levels({})","levels({'b': ['a'], 'c': ['a', 'b'], 'd': []})","levels({'x': ['y'], 'y': ['x']})","levels({'load': ['clean', 'dims'], 'clean': ['extract'], 'dims': ['extract'], 'report': ['load']})"]}$df$::jsonb, $df${"cases":["ea901b692e0075fd3aa505be2746eb24aa6a7ccfec5956f5ba081eedb4d4fb15","efb68763fff156b99d50e5924aa8bd52dc08ccb8222edae031b94d6fb85a2344","7dc7b6b7545843ecfcdad04f27534bef7543c3007dd2576a454dd6a58a65ac08","582a8130f8637bf6204a13873e1265faad073e9f00e24536046b4065f1a32eff"]}$df$::jsonb, $df$def levels(deps):
    nodes = set(deps) | {u for ups in deps.values() for u in ups}
    indeg = {n: 0 for n in nodes}
    down = {n: [] for n in nodes}
    for t, ups in deps.items():
        for u in set(ups):
            indeg[t] += 1
            down[u].append(t)
    cur = sorted(n for n in nodes if indeg[n] == 0)
    out, seen = [], 0
    while cur:
        out.append(cur)
        seen += len(cur)
        nxt = []
        for n in cur:
            for d in down[n]:
                indeg[d] -= 1
                if indeg[d] == 0:
                    nxt.append(d)
        cur = sorted(nxt)
    if seen != len(nodes):
        raise ValueError('cycle')
    return out
$df$, $df$Kahn's algorithm processed level by level: every task whose upstreams are done joins the next level; leftover tasks mean a cycle.$df$),
($df$as-py-11$df$, 'python', $df$Retry with backoff and a dead-letter list$df$, $df$Hard$df$, $df$Reliability$df$, $df${"problem":"Write `process(messages, handler, max_tries)` that calls `handler(m)` for each message, retrying a message that raises until it has been tried max_tries times. Return (done, dead, delays): done = results of successful calls in order, dead = messages that never succeeded, delays = the backoff waits that would be slept, 2**(n-1) seconds before the n-th retry, in call order.","starter":"def process(messages, handler, max_tries):\n    raise NotImplementedError\n","example":"process([1, 2], lambda m: m * 10, 3)  ->  ([10, 20], [], [])","cases":["process([], lambda m: m, 3)","process([1, 2], lambda m: m * 10, 3)","process([1, 0, 2], lambda m: 10 // m, 3)","process(['ok', 'bad'], lambda m: m.upper() if m == 'ok' else int(m), 4)"]}$df$::jsonb, $df${"cases":["98f32a601bd2eb3b46f117f15970440b8a62acc69e05fde8fc95c3e2dda6ffc4","0dc6b65880161e460701470a3aa37301355e68cb524f6e23fe3792d0f115eebc","6320005eadcdb722b41765d336a73f25f31f8de813838003d1dd472467d37028","db4e8331d564fcc12092e6f63f6cb92802b37e9771d42dff013e2c297fda7e07"]}$df$::jsonb, $df$def process(messages, handler, max_tries):
    done, dead, delays = [], [], []
    for m in messages:
        for attempt in range(1, max_tries + 1):
            try:
                done.append(handler(m))
                break
            except Exception:
                if attempt == max_tries:
                    dead.append(m)
                else:
                    delays.append(2 ** (attempt - 1))
    return done, dead, delays
$df$, $df$A bounded retry loop per message; the delay before retry n is 2^(n-1), and a message that fails every try goes to the dead-letter list instead of stopping the batch.$df$),
($df$as-py-12$df$, 'python', $df$Tumbling-window counts with late events$df$, $df$Hard$df$, $df$Streaming$df$, $df${"problem":"Write `window_counts(events, size, lateness)` for events `(ts, key)` with integer timestamps arriving in the given order. Count events per (window_start, key) where window_start = ts // size * size. The watermark is the max ts seen so far minus lateness; an event whose window ended at or before the watermark (window_start + size <= watermark) is dropped as late. Return (counts as a sorted list of (window_start, key, n), number of dropped events).","starter":"def window_counts(events, size, lateness):\n    raise NotImplementedError\n","example":"window_counts([(1, 'a'), (2, 'a'), (11, 'b')], 10, 0)  ->  ([(0, 'a', 2), (10, 'b', 1)], 0)","cases":["window_counts([], 10, 0)","window_counts([(1, 'a'), (2, 'a'), (11, 'b')], 10, 0)","window_counts([(25, 'a'), (3, 'a'), (19, 'b'), (14, 'b')], 10, 5)","window_counts([(0, 'x'), (40, 'x'), (35, 'x'), (5, 'x')], 10, 10)"]}$df$::jsonb, $df${"cases":["0ce6eb16a586f0970d7635994d8641657b39c78122b6202ae686c02b0b216413","2cfe26d288af0f5ce462774a6e8b657b51f1079f92d73febae9754ce8fc76391","abbc046e17db7e5c8b7e72d54a1f7ac734621abe70c92e390486551eb870db6e","9886974b407590e4f991abedaafdb7571d047054a16e408dedd35334611b297b"]}$df$::jsonb, $df$def window_counts(events, size, lateness):
    counts, dropped, max_ts = {}, 0, None
    for ts, key in events:
        start = ts // size * size
        if max_ts is not None and start + size <= max_ts - lateness:
            dropped += 1
            continue
        counts[(start, key)] = counts.get((start, key), 0) + 1
        max_ts = ts if max_ts is None else max(max_ts, ts)
    return sorted((s, k, n) for (s, k), n in counts.items()), dropped
$df$, $df$The watermark trails the newest timestamp by the allowed lateness; events for windows that closed before it are counted as dropped, the rest are aggregated per window and key.$df$)
